# Kaggle GPU STILLS from the cloud queue (cloud/queue/*.json). Generated by `python -m tc queue kaggle <id> ...`,
# which writes the requests below into this file, so the requests need not be pushed (the scene CODE must be on the
# branch). Runs as a Kaggle "script" kernel: Accelerator = GPU, Internet = On (set by kernel-metadata.json).
# For each request: download its free scans -> render on the GPU (Cycles + OpenImageDenoise) -> check the images
# (missing / black / broken = failed) -> optional film finish. Output tab: out/ (images + _results/<id>.json + logs).
import json, os, shutil, subprocess, sys, time

ENTRIES = json.loads({{ENTRIES_JSON}})       # the queue requests (filled in by the generator)
REPO = "{{REPO}}"                            # public repo, nothing secret needed
BRANCH = "{{BRANCH}}"
R2_PUBLIC_URL = "{{R2_PUBLIC_URL}}"          # optional public read URL of the asset cache ('' = Poly Haven)
CODE, TOOLS, WORK = "/kaggle/tmp/tc", "/kaggle/tmp/tools", "/kaggle/working"   # /kaggle/tmp is not saved


def sh(cmd):
    print("$", " ".join(cmd), flush=True)
    subprocess.run(cmd, check=True)


subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv"])
if not os.path.isdir(CODE):
    sh(["git", "clone", "--depth", "1", "-b", BRANCH, REPO, CODE])
os.chdir(CODE)
sh([sys.executable, "-m", "pip", "install", "-q", "numpy", "pillow"])
t0 = time.time()
BLENDER = subprocess.run(["bash", "cloud/setup_blender_linux.sh", TOOLS], capture_output=True, text=True,
                         check=True).stdout.strip().splitlines()[-1]
print(f"blender: {BLENDER}  (install {time.time() - t0:.0f} s)")
if R2_PUBLIC_URL:
    os.environ["TC_R2_PUBLIC_URL"] = R2_PUBLIC_URL
os.environ["TC_SCANS_CAP_GB"] = "15"         # Kaggle has plenty of scratch disk

summary = {}
for e in ENTRIES:
    done = f"{WORK}/out/_results/{e['id']}.json"
    if os.path.exists(done) and json.load(open(done)).get("status") == "done":
        summary[e["id"]] = "done (earlier)"                   # resume: already rendered in this session
        continue
    q = f"/kaggle/tmp/queue/{e['id']}.json"
    os.makedirs(os.path.dirname(q), exist_ok=True)
    json.dump(e, open(q, "w"))
    r = subprocess.run([sys.executable, "-m", "tc", "queue", "run", q, "--blender", BLENDER, "--gpu"])
    res = f"{CODE}/out/_results/{e['id']}.json"
    summary[e["id"]] = json.load(open(res)) if os.path.exists(res) else {"status": "failed", "exit": r.returncode}
    shutil.copytree(f"{CODE}/out", f"{WORK}/out", dirs_exist_ok=True)   # save after every request (crash-safe)

for k, v in summary.items():
    print(k, "->", v if isinstance(v, str) else f"{v['status']}, {v.get('seconds')} s, images {v.get('images')}")
